package com.vectora.api;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class VectoraRepository {private final JdbcTemplate jdbc;public VectoraRepository(JdbcTemplate jdbc){this.jdbc=jdbc;} public Map<String,Object> dashboard(){Map<String,Object> m=new LinkedHashMap<>();m.put("onlineCameras",jdbc.queryForObject("select count(*) from cameras where status <> 'OFFLINE'",Long.class));m.put("activeDrones",jdbc.queryForObject("select count(*) from drones where status in ('IN_FLIGHT','RETURNING')",Long.class));m.put("openEvents",jdbc.queryForObject("select count(*) from events where status in ('NEW','INVESTIGATING')",Long.class));m.put("activeMissions",jdbc.queryForObject("select count(*) from missions where status='IN_PROGRESS'",Long.class));m.put("criticalEvents",jdbc.queryForObject("select count(*) from events where severity='CRITICAL' and status <> 'RESOLVED'",Long.class));return m;} public List<Map<String,Object>> cameras(){return jdbc.queryForList("select * from cameras order by id");} public List<Map<String,Object>> sensors(){return jdbc.queryForList("select * from sensors order by id");} public List<Map<String,Object>> drones(){return jdbc.queryForList("select * from drones order by status,id");} public List<Map<String,Object>> missions(){return jdbc.queryForList("select m.*,d.code as drone_code from missions m left join drones d on d.id=m.drone_id order by m.start_at desc");} public List<Map<String,Object>> geofences(){return jdbc.queryForList("select * from geofences order by id");} public List<Map<String,Object>> events(){return jdbc.queryForList("select * from events order by created_at desc");} public List<Map<String,Object>> audit(){return jdbc.queryForList("select * from audit_events order by created_at desc");} public void simulate(String type,String source){String code="SIM-"+System.currentTimeMillis();jdbc.update("insert into events(event_code,event_type,severity,source_type,source_code,zone,message,status,latitude,longitude) values(?,?,?,?,?,?,?,?,?,?)",code,type,"HIGH",type.contains("DRONE")?"DRONE":"CAMERA",source,"Simulação","Evento simulado pelo operador · "+type,"NEW",-23.5505,-46.6333);} }
